),plans as (
 select c.case_key,m.v->'roles' roles,
 jsonb_agg(o.value||jsonb_build_object(
  'authorized_roles',m.v->'roles',
  'protects_role_interest',coalesce((o.value->>'lawful')::boolean,false) and m.v->>'interest' is not null,
  'role_interest_note',case when coalesce((o.value->>'lawful')::boolean,false) then m.v->'interest' else 'null'::jsonb end,
  'description',regexp_replace(split_part(o.value->>'description',' Стратегический критерий:',1),'компетенции: [^.]*\.','компетенции: '||(select string_agg(t,', ') from jsonb_array_elements_text(m.v->'roles') t)||'.')||case when coalesce((o.value->>'lawful')::boolean,false) and m.v->>'interest' is not null then ' Стратегический критерий: '||(m.v->>'interest') else '' end
 ) order by o.n) options
 from private.authored_event_catalog c join metadata m on m.v->>'case_key'=c.case_key
 cross join lateral jsonb_array_elements(c.content#>'{effect_plan,options}') with ordinality o(value,n)
 group by c.case_key,m.v
)
update private.authored_event_catalog c set content=jsonb_set(jsonb_set(c.content,'{allowed_roles}',p.roles),'{effect_plan,options}',p.options) from plans p where p.case_key=c.case_key;
update public.event_cases e set allowed_roles=array(select jsonb_array_elements_text(c.content->'allowed_roles')),effect_plan=c.content->'effect_plan'
from private.authored_event_catalog c where e.case_key=c.case_key and c.case_key like 'bank-legal-2026-%' and not exists(select 1 from event_case_outcomes o where o.case_id=e.id);
